#[inline]
fn alu_add(bits: u32, a: u64, b: u64) -> u64 {
    a.wrapping_add(b) & mask(bits)
}
#[inline]
fn alu_xor(bits: u32, a: u64, b: u64) -> u64 {
    (a ^ b) & mask(bits)
}
#[inline]
fn alu_and(bits: u32, a: u64, b: u64) -> u64 {
    (a & b) & mask(bits)
}

